function payoutEnsureTable(PDO $pdo): void {
    $pdo->exec("CREATE TABLE IF NOT EXISTS provider_payouts (
      payout_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, booking_domain VARCHAR(20) NOT NULL,
      booking_id INT NOT NULL, booking_reference VARCHAR(20) NOT NULL, provider_type VARCHAR(30) NOT NULL,
      provider_id INT NULL, provider_key VARCHAR(80) NOT NULL, provider_name VARCHAR(190) NOT NULL,
      gross_amount DECIMAL(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'pending',
      approved_by_admin_id INT NULL, approved_at DATETIME NULL, settlement_method VARCHAR(40) NULL,
      settlement_reference VARCHAR(120) NULL, settlement_note VARCHAR(500) NULL,
      settled_by_admin_id INT NULL, settled_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      PRIMARY KEY (payout_id), UNIQUE KEY uq_provider_booking (booking_domain,booking_id,provider_key),
      KEY idx_payout_status (status), KEY idx_payout_provider (provider_type,provider_id), KEY idx_payout_settled (settled_at)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
function payoutSyncLedger(PDO $pdo): void {
    $pdo->exec("UPDATE provider_payouts p JOIN bookings b ON b.booking_id=p.booking_id AND p.booking_domain=LOWER(b.booking_type)
      LEFT JOIN operators o ON o.operator_id=b.operator_id LEFT JOIN tour_guides tg ON tg.guide_id=b.guide_id LEFT JOIN boats bt ON bt.boat_id=b.boat_id
      SET p.provider_type=CASE LOWER(b.booking_type) WHEN 'package' THEN 'operator' WHEN 'tourguide' THEN 'tourguide' ELSE 'boat' END,
        p.provider_id=CASE LOWER(b.booking_type) WHEN 'package' THEN b.operator_id WHEN 'tourguide' THEN b.guide_id ELSE b.boat_id END,
        p.provider_key=CONCAT(CASE LOWER(b.booking_type) WHEN 'package' THEN 'operator' WHEN 'tourguide' THEN 'tourguide' ELSE 'boat' END,':',COALESCE(CASE LOWER(b.booking_type) WHEN 'package' THEN b.operator_id WHEN 'tourguide' THEN b.guide_id ELSE b.boat_id END,0)),
        p.provider_name=COALESCE(NULLIF(TRIM(CASE LOWER(b.booking_type) WHEN 'package' THEN o.fullname WHEN 'tourguide' THEN tg.fullname ELSE bt.name END),''),p.provider_name),
        p.booking_reference=COALESCE(NULLIF(b.booking_reference,''),p.booking_reference),p.gross_amount=GREATEST(COALESCE(b.payment_amount,0),0),p.updated_at=NOW()
      WHERE p.status='pending'");
    $pdo->exec("INSERT INTO provider_payouts
      (booking_domain,booking_id,booking_reference,provider_type,provider_id,provider_key,provider_name,gross_amount,status)
      SELECT LOWER(b.booking_type),b.booking_id,COALESCE(NULLIF(b.booking_reference,''),CONCAT('BK-',b.booking_id)),
        CASE LOWER(b.booking_type) WHEN 'package' THEN 'operator' WHEN 'tourguide' THEN 'tourguide' ELSE 'boat' END,
        CASE LOWER(b.booking_type) WHEN 'package' THEN b.operator_id WHEN 'tourguide' THEN b.guide_id ELSE b.boat_id END,
        CONCAT(CASE LOWER(b.booking_type) WHEN 'package' THEN 'operator' WHEN 'tourguide' THEN 'tourguide' ELSE 'boat' END,':',COALESCE(CASE LOWER(b.booking_type) WHEN 'package' THEN b.operator_id WHEN 'tourguide' THEN b.guide_id ELSE b.boat_id END,0)),
        COALESCE(NULLIF(TRIM(CASE LOWER(b.booking_type) WHEN 'package' THEN o.fullname WHEN 'tourguide' THEN tg.fullname ELSE bt.name END),''),
          CASE LOWER(b.booking_type) WHEN 'package' THEN 'Unassigned tour operator' WHEN 'tourguide' THEN 'Unassigned tour guide' ELSE COALESCE(NULLIF(TRIM(b.preferred_resource),''),'Unassigned boat') END),
        GREATEST(COALESCE(b.payment_amount,0),0),'pending'
      FROM bookings b LEFT JOIN operators o ON o.operator_id=b.operator_id
      LEFT JOIN tour_guides tg ON tg.guide_id=b.guide_id LEFT JOIN boats bt ON bt.boat_id=b.boat_id
      WHERE COALESCE(b.payment_amount,0)>0 AND NOT EXISTS (SELECT 1 FROM provider_payouts existing WHERE existing.booking_domain=LOWER(b.booking_type) AND existing.booking_id=b.booking_id)
      ON DUPLICATE KEY UPDATE booking_reference=VALUES(booking_reference),provider_name=VALUES(provider_name),
        gross_amount=IF(provider_payouts.status='pending',VALUES(gross_amount),provider_payouts.gross_amount),updated_at=NOW()");
    $pdo->exec("UPDATE provider_payouts p JOIN hotel_room_bookings hb ON hb.hotel_booking_id=p.booking_id AND p.booking_domain='hotel'
      LEFT JOIN hotel_resorts hr ON hr.hotel_resort_id=hb.hotel_resort_id
      SET p.provider_id=hb.hotel_resort_id,p.provider_key=CONCAT('hotel:',COALESCE(hb.hotel_resort_id,0)),
        p.provider_name=COALESCE(NULLIF(TRIM(hr.name),''),p.provider_name),p.booking_reference=COALESCE(NULLIF(hb.booking_reference,''),p.booking_reference),
        p.gross_amount=GREATEST(COALESCE(hb.amount_paid,0),0),p.updated_at=NOW() WHERE p.status='pending'");
    $pdo->exec("INSERT INTO provider_payouts
      (booking_domain,booking_id,booking_reference,provider_type,provider_id,provider_key,provider_name,gross_amount,status)
      SELECT 'hotel',hb.hotel_booking_id,COALESCE(NULLIF(hb.booking_reference,''),CONCAT('HR-',hb.hotel_booking_id)),
        'hotel',hb.hotel_resort_id,CONCAT('hotel:',COALESCE(hb.hotel_resort_id,0)),
        COALESCE(NULLIF(TRIM(hr.name),''),'Unassigned hotel / resort'),GREATEST(COALESCE(hb.amount_paid,0),0),'pending'
      FROM hotel_room_bookings hb LEFT JOIN hotel_resorts hr ON hr.hotel_resort_id=hb.hotel_resort_id
      WHERE COALESCE(hb.amount_paid,0)>0 AND NOT EXISTS (SELECT 1 FROM provider_payouts existing WHERE existing.booking_domain='hotel' AND existing.booking_id=hb.hotel_booking_id)
      ON DUPLICATE KEY UPDATE booking_reference=VALUES(booking_reference),provider_name=VALUES(provider_name),
        gross_amount=IF(provider_payouts.status='pending',VALUES(gross_amount),provider_payouts.gross_amount),updated_at=NOW()");
}
function payoutMoney(float $amount): string { return '₱'.number_format($amount,2); }
function payoutLabel(string $value): string { return match(strtolower(trim($value))){
  'package'=>'Tour Package','tourguide'=>'Tour Guide','boat'=>'Boat','hotel'=>'Hotel / Resort','operator'=>'Tour Operator',
  'bank_transfer'=>'Bank Transfer','e_wallet'=>'E-wallet',default=>ucwords(str_replace(['_','-'],' ',$value))}; }
function payoutCsvSafe(string $value): string { return preg_match('/^\s*[=+\-@]/u',$value)?"'".$value:$value; }
function payoutRedirect(string $type,string $message): never { $_SESSION['payout_notice']=['type'=>$type,'message'=>$message];header('Location: adearningsdisbursements.php');exit; }
/** @return array{applicable:bool,ready:bool,amount:float,note:string} */
function payoutRetentionAssessment(array $record): array {
  $completion=strtolower(trim((string)($record['completion_status']??'')));
  $policy=strtolower(trim((string)($record['refund_policy']??'')));
  $requestStatus=strtolower(trim((string)($record['cancellation_status']??$record['request_status']??'')));
  $refundStatus=strtolower(trim((string)($record['request_refund_status']??$record['refund_status']??'')));
  $paid=max(0.0,(float)($record['amount_paid']??$record['gross_amount']??0));
  $retained=min($paid,max(0.0,(float)($record['non_refundable_amount']??0)));
  $refundable=max(0.0,(float)($record['refundable_amount']??0));
  $applicable=$completion==='cancelled'&&in_array($policy,['partial_refund','deposit_non_refundable'],true)&&$retained>0.009;
  $refundComplete=$refundable<=0.009||in_array($refundStatus,['completed','refunded','succeeded','not_applicable'],true);
  $ready=$applicable&&$requestStatus==='completed'&&$refundComplete;
  $note=$applicable
    ? 'Late-cancellation policy: '.payoutMoney($retained).' was retained as the non-refundable portion (up to 20% of the booking total).'.($ready?' The cancellation and required refund are complete, so this retained amount may be settled to the provider.':' Settlement remains locked until the cancellation and required refund are completed.')
    : '';
  return ['applicable'=>$applicable,'ready'=>$ready,'amount'=>$applicable?$retained:0.0,'note'=>$note];
}

payoutEnsureTable($pdo);
