 if(!isset($providers[$key]))$providers[$key]=['name'=>$row['provider_name'],'type'=>$row['provider_type'],'pending'=>0.0,'available'=>0.0,'settled'=>0.0,'bookings'=>0];$providers[$key][$state]+=$amount;$providers[$key]['bookings']++;}
uasort($providers,fn($a,$b)=>(($b['pending']+$b['available'])<=>($a['pending']+$a['available'])));
