foreach($allRows as $row){$k=substr((string)$row['booking_created'],0,7);if(in_array($k,$monthKeys,true))$collectionMap[$k]=($collectionMap[$k]??0)+(float)$row['amount_paid'];}
foreach($pdo->query("SELECT DATE_FORMAT(settled_at,'%Y-%m') month_key,SUM(gross_amount) amount FROM provider_payouts WHERE status='settled' AND settled_at>=DATE_FORMAT(CURRENT_DATE-INTERVAL 5 MONTH,'%Y-%m-01') GROUP BY month_key")->fetchAll(PDO::FETCH_ASSOC) as $row)$settledMap[(string)$row['month_key']]=(float)$row['amount'];
$chartCollections=array_map(fn($k)=>$collectionMap[$k]??0,$monthKeys);$chartSettled=array_map(fn($k)=>$settledMap[$k]??0,$monthKeys);
$pageRecords=array_map(static fn(array $row):array=>['provider_key'=>(string)$row['provider_key'],'provider_type'=>strtolower((string)$row['provider_type']),'provider_name'=>(string)$row['provider_name'],'state'=>(string)$row['workflow_status'],'payout'=>(float)$row['payout_amount'],'collected'=>(float)$row['amount_paid'],'booking_month'=>substr((string)$row['booking_created'],0,7),'settled_month'=>!empty($row['settled_at'])?substr((string)$row['settled_at'],0,7):''],$allRows);
